import java.util.Scanner;

public class Problems {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int B = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < arr.length; i++) {
            arr[i] = sc.nextInt();
        }

        int[] buckets = new int[101];
        int sum = 0;

        int evens = 0;
        int odds = 0;
        int start = 0;
        int count = 0;
        int k = 1;

        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] % 2 == 0) {
                evens++;
            } else {
                odds++;
            }

            if (evens == odds) {
                int diff = Math.abs(arr[i + 1] - arr[i]);
                int max = bucketMax(buckets);
                if (sum > B && diff < max) {
                    sum -= max;
                    buckets[max]--;
                    buckets[diff]++;
                    sum += diff;
                } else if (sum < B){
                    sum += diff;
                    buckets[diff]++;
                    count++;
                    start = i + 1;
                }
                if (i == arr.length - 2 && k < arr.length - 1) {
                    i = start++;
                    evens = odds = 0;
                }
            }

        }
        int i = buckets.length - 1;
        while (sum > B) {
            if (buckets[i] > 0) {
                sum -= i;
                count--;
            } else {
                i--;
            }
        }

        System.out.println(count);
    }

    private static int bucketMax(int[] buckets) {
        for (int i = buckets.length - 1; i >= 0; i--) {
            if (buckets[i] > 0) {
                return i;
            }
        }
        return -1;
    }
}
